import numpy as np
# Two copies of one tanh ESN, different initial states, same input: does the gap close?
def gap_after(radius, in_scale, steps=200, N=100, seed=0):
    r = np.random.default_rng(seed)
    W = r.normal(size=(N, N)); W *= radius / max(abs(np.linalg.eigvals(W)))
    w_in = r.uniform(-1, 1, N) * in_scale
    u = r.uniform(-1, 1, steps)
    x, z = r.uniform(-1, 1, N), r.uniform(-1, 1, N)
    for t in range(steps):
        x = np.tanh(W @ x + w_in * u[t]); z = np.tanh(W @ z + w_in * u[t])
    return np.linalg.norm(x - z), np.linalg.norm(W, 2)
for radius in (0.8, 1.1, 1.5):
    for in_scale in (0.1, 2.0):
        g, smax = gap_after(radius, in_scale)
        print(f"rho(W)={radius}  sigma_max(W)={smax:.2f}  input scale {in_scale}: gap after 200 steps = {g:.1e}")
